// Mock asset catalog. Every title and ID here is invented.
// Returns { status, body } and lets Respond to Webhook turn that into a real HTTP response.

const catalog = {
  'TT-0142': { asset_id: 'TT-0142', title: 'Harbor Lights S02E07',   type: 'episode', duration_min: 47,  mezzanine_bitrate_mbps: 8,    platform: 'Max',        status: 'qc_hold',   deadline: '2026-09-25' },
  'TT-0217': { asset_id: 'TT-0217', title: 'The Quiet Meridian',     type: 'feature', duration_min: 112, mezzanine_bitrate_mbps: 22.7, platform: 'Max',        status: 'encoding',  deadline: '2026-10-02' },
  'TT-0288': { asset_id: 'TT-0288', title: 'Salt Flats S01E01',      type: 'episode', duration_min: 52,  mezzanine_bitrate_mbps: 8,    platform: 'Discovery+', status: 'delivered', deadline: '2026-09-12' },
  'TT-0301': { asset_id: 'TT-0301', title: 'Salt Flats S01E02',      type: 'episode', duration_min: 49,  mezzanine_bitrate_mbps: 8,    platform: 'Discovery+', status: 'delivered', deadline: '2026-09-12' },
  'TT-0356': { asset_id: 'TT-0356', title: 'Night Kitchen 30s promo', type: 'promo',  duration_min: 0.5, mezzanine_bitrate_mbps: 15,   platform: 'Both',       status: 'ingested',  deadline: '2026-09-22' },
  'TT-0410': { asset_id: 'TT-0410', title: 'Orbital Decay trailer',  type: 'trailer', duration_min: 2.5, mezzanine_bitrate_mbps: 15,   platform: 'Both',       status: 'qc_hold',   deadline: '2026-09-21' },
  'TT-0477': { asset_id: 'TT-0477', title: 'Harbor Lights S02E08',   type: 'episode', duration_min: 45,  mezzanine_bitrate_mbps: 8,    platform: 'Max',        status: 'ingested',  deadline: '2026-10-01' },
  'TT-0503': { asset_id: 'TT-0503', title: 'Copper Canyon S03E04',   type: 'episode', duration_min: 44,  mezzanine_bitrate_mbps: 8,    platform: 'Discovery+', status: 'encoding',  deadline: '2026-09-30' },
  'TT-0619': { asset_id: 'TT-0619', title: 'The Long Thaw',          type: 'feature', duration_min: 96,  mezzanine_bitrate_mbps: 22.7, platform: 'Max',        status: 'delivered', deadline: '2026-08-30' },
  'TT-0731': { asset_id: 'TT-0731', title: 'Night Kitchen S01E05',   type: 'episode', duration_min: 28,  mezzanine_bitrate_mbps: 8,    platform: 'Both',       status: 'encoding',  deadline: '2026-09-28' },
};

const id = String($input.first().json.query.id || '').trim().toUpperCase();

// 400: the caller left out the one parameter this endpoint needs
if (!id) {
  return [{ json: { status: 400, body: { error: 'missing required query parameter: id' } } }];
}

// 500: this ID always fails, on purpose. It exists to test what the agent does with a hard failure.
if (id === 'TT-0500') {
  return [{ json: { status: 500, body: { error: 'upstream MAM timeout', asset_id: id } } }];
}

// 503: this ID fails two calls out of every three, on purpose, so a retry has something to recover from.
// The counter lives in workflow static data, which only persists for production executions of an active workflow.
if (id === 'TT-0503') {
  const state = $getWorkflowStaticData('global');
  state.calls = (state.calls || 0) + 1;
  if (state.calls % 3 !== 0) {
    return [{ json: { status: 503, body: { error: 'MAM busy, retry later', asset_id: id, attempt: state.calls } } }];
  }
}

const asset = catalog[id];

// 404: a well-formed request for something that does not exist
if (!asset) {
  return [{ json: { status: 404, body: { error: 'asset not found', asset_id: id } } }];
}

return [{ json: { status: 200, body: asset } }];
